#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the attended hardware gate for issue #26, candidate 625d5a2.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=17

# ── Bound candidate identity. Changing any of these is a new candidate. ──
CANDIDATE_COMMIT=625d5a22c57d7ab0f792330a3bb7eaa0880f7304
CANDIDATE_TREE=8f3e33a03b1609d2957c63367a4a9c471b6e4ef6
ARCHIVE_SHA256=1eb0a56ca3cff03012884ef7cb7e8dc0c659b8b8db4ccf39d52a0fb75b3a9e5f
SIGNATURE_SHA256=0327309429e43375b02a029efeee7ab5cfbf5242ff0205c03715872769b0e94a
SIGNING_KEY=0B1C5414F8D18F8B6AA78957335FEBC82DB247EC

HERE="$(cd "$(dirname "$0")" && pwd)"
REPO="${HIBERMACHY_REPO:-$(cd "$HERE/.." && pwd)}"
CHECKPOINT="$REPO/verification/ticket-26/hibernation-checkpoint.sh"

RUN_ID="$(date -u +%Y%m%dT%H%M%SZ)"
RUN_DIR="$HERE/ticket-26-run-$RUN_ID"
RECORD="$RUN_DIR/evidence-record.md"
STATE_DIR="$RUN_DIR/checkpoints"
BASELINE="$RUN_DIR/baseline"

# Consecutive-cycle count. AC5: any unexplained anomaly restarts this at zero.
CONSECUTIVE=0
ANOMALIES=0

# ── Recording helpers ─────────────────────────────────────────────────────
# Evidence is appended as it is observed, never buffered to the end, so an
# interrupted run still leaves the record of everything already seen.

rec() { printf '%s\n' "$*" >> "$RECORD"; }

# row "Item" "RESULT" "evidence" — one line of a markdown results table.
row() {
  printf '| %s | %s | %s |\n' "$1" "$2" "${3//|/\\|}" >> "$RECORD"
  case $2 in
    PASS)    printf '  %s✓ %s%s — %s\n' "$GREEN"  "$1" "$RESET" "$2" ;;
    FAIL)    printf '  %s✗ %s%s — %s\n' "$RED"    "$1" "$RESET" "$2" ;;
    *)       printf '  %s· %s%s — %s\n' "$DIM"    "$1" "$RESET" "$2" ;;
  esac
}

# ask_result VAR "Item" — the operator records PASS, FAIL or NOT RUN.
# There is no default and blank is not accepted: a blank must never read as a
# pass. This is the project's standing rule, and three candidates were
# invalidated for inferred completion records.
ask_result() {
  local __var=$1 item=$2 reply=""
  while true; do
    printf '  %s%s%s\n' "$BOLD" "$item" "$RESET"
    printf '  %sp%s = PASS   %sf%s = FAIL   %sn%s = NOT RUN  ' \
      "$GREEN" "$RESET" "$RED" "$RESET" "$DIM" "$RESET"
    read -r reply || true
    case ${reply,,} in
      p|pass)     printf -v "$__var" '%s' PASS;    return 0 ;;
      f|fail)     printf -v "$__var" '%s' FAIL;    return 0 ;;
      n|notrun|'not run') printf -v "$__var" '%s' 'NOT RUN'; return 0 ;;
      *) warn "Answer p, f or n. A blank entry never counts as a pass." ;;
    esac
  done
}

# note_evidence "prompt" -> echoes a sanitized free-text observation.
# The operator is reminded not to paste identifiers; the record is publishable.
ask_evidence() {
  local __var=$1 prompt=$2 input=""
  printf '  %s%s%s\n' "$BOLD" "$prompt" "$RESET"
  note 'Sanitize: no hostnames, usernames, boot/session IDs, serials or raw journal text.'
  printf '  > '
  read -r input || true
  printf -v "$__var" '%s' "${input:-none recorded}"
}

# anomaly "what happened" — AC5. Investigation first, then the count restarts.
anomaly() {
  ANOMALIES=$((ANOMALIES + 1))
  CONSECUTIVE=0
  warn "ANOMALY: $1"
  say 'AC5: an unexplained anomaly blocks promotion and restarts the'
  say 'consecutive-cycle count at zero, only after investigation.'
  local cause=""
  ask_evidence cause 'Record the investigation and cause (sanitized):'
  rec ""
  rec "> **Anomaly $ANOMALIES.** $1"
  rec ">"
  rec "> Investigation: $cause"
  rec ">"
  rec "> Consecutive-cycle count restarted at zero."
  rec ""
  say "Consecutive cycle count is now 0."
  pause 'Press Enter to continue.'
}

# ── Live product surface (read-only) ──────────────────────────────────────
# The real IPC target and the real callable names, as declared in
# plugin/Service.qml:1521-1537. Nothing here mutates or sleeps.

# Reach the plugin through omarchy-shell, the documented Quattro seam. A bare
# `quickshell ipc call` cannot locate the running shell: Omarchy starts it as
# `quickshell -n -p /usr/share/omarchy/shell` and there is no default config
# path, so the bare form exits non-zero no matter how healthy the plugin is.
hb_status_raw() { omarchy-shell dev.hibermachy status 2>/dev/null || true; }

# quickshell reports failures on stdout, not stderr, so "non-empty" is not
# evidence that a capture succeeded. Only valid JSON is.
is_json() { [[ -s $1 ]] && python3 -c 'import json,sys; json.load(open(sys.argv[1]))' "$1" 2>/dev/null; }

# hb_field NAME — one field from the status snapshot, or a marker.
hb_field() {
  hb_status_raw | python3 -c '
import json, sys
try:
    doc = json.load(sys.stdin)
except Exception:
    print("<status-unavailable>"); raise SystemExit(0)
value = doc.get(sys.argv[1], "<absent>")
print(json.dumps(value) if isinstance(value, (dict, list)) else value)
' "$1" 2>/dev/null || printf '<status-unavailable>'
}

# hb_last_reason — reasonCode of the most recent outcome in history.
hb_last_reason() {
  hb_status_raw | python3 -c '
import json, sys
try:
    doc = json.load(sys.stdin)
except Exception:
    print("<status-unavailable>"); raise SystemExit(0)
history = doc.get("outcomeHistory") or []
print(history[-1].get("reasonCode", "<absent>") if history else "<empty-history>")
' 2>/dev/null || printf '<status-unavailable>'
}

show_status() {
  local auto manual stay inhib rearm hero
  auto=$(hb_field automaticBlockerReasonCode)
  manual=$(hb_field manualBlockerReasonCode)
  stay=$(hb_field stayAwake)
  inhib=$(hb_field compositorIdleInhibited)
  rearm=$(hb_field rearmRequired)
  hero=$(hb_field heroStatus)
  note "heroStatus=$hero  stayAwake=$stay  compositorIdleInhibited=$inhib"
  note "rearmRequired=$rearm"
  note "automaticBlockerReasonCode=$auto"
  note "manualBlockerReasonCode=$manual"
  note "lastOutcomeReasonCode=$(hb_last_reason)"
}

# ── A behavioural case that must NOT sleep ────────────────────────────────
# expect_reason CASE EXPECTED_CODE FIELD — records observed versus expected.
suppression_case() {
  local case_name=$1 expected=$2 field=$3
  local observed result detail
  observed=$(hb_field "$field")
  say "Expected $field: $expected"
  say "Observed $field: $observed"
  show_status
  if [[ $observed == "$expected" ]]; then
    note 'Observed code matches the expected code.'
  else
    warn 'Observed code does NOT match. Record FAIL unless you can explain it.'
  fi
  ask_result result "$case_name"
  ask_evidence detail 'Observation (what you saw, and that no sleep occurred):'
  row "$case_name" "$result" "expected=$expected observed=$observed; $detail"
  [[ $result == FAIL ]] && anomaly "$case_name failed"
  return 0
}

# ── One physical staged-sleep / hibernate / resume cycle ──────────────────
# The wizard never triggers sleep. The operator does, through the real
# product journey, and this records what the operator externally observed.
physical_cycle() {
  local label=$1 origin=$2

  say "Cycle: $origin"
  printf '\n'
  step 'Taking the external pre-sleep checkpoint now.'
  if ! "$CHECKPOINT" record "$label" "$STATE_DIR"; then
    warn 'Checkpoint could not be recorded. Do not proceed with this cycle.'
    row "Cycle $label ($origin)" 'NOT RUN' 'external pre-sleep checkpoint failed'
    return 1
  fi
  printf '\n'
  warn 'From here the machine will really sleep. Save anything still open.'
  pause 'Press Enter when you are ready to begin the cycle.'

  _clear
  printf '\n%s%s▸ Cycle %s in progress · %s%s\n\n' "$BOLD" "$BLUE" "$label" "$origin" "$RESET"
  say 'Now do the following, then come back to this terminal after resume:'
  printf '\n'
  return 0
}

# finish_cycle LABEL ORIGIN — runs after the operator has resumed.
finish_cycle() {
  local label=$1 origin=$2
  local verify_status verify_out observed_down result detail

  printf '\n'
  step 'Verifying the external checkpoint survived into this same session.'
  set +e
  verify_out=$("$CHECKPOINT" verify "$label" "$STATE_DIR" 2>&1)
  verify_status=$?
  set -e
  printf '%s\n' "$verify_out" | sed 's/^/  /'
  printf '\n'

  say 'AC4 requires evidence the product cannot supply for itself:'
  note 'A Hibermachy "Completed" result and free-form journal text cannot'
  note 'certify hibernation. Your own observation is what does.'
  printf '\n'
  if confirm 'Did you SEE the machine fully powered down (screen dark, no fans, no power LED)?'; then
    observed_down=yes
  else
    observed_down=no
    warn 'Without an external powered-down observation this cycle cannot'
    warn 'certify hibernation, however clean the checkpoint looks.'
  fi

  local checkpoint_verdict
  case $verify_status in
    0) checkpoint_verdict='CONFIRMED same-session restoration' ;;
    1) checkpoint_verdict='BROKEN - session did not survive' ;;
    2) checkpoint_verdict='INDETERMINATE - no real sleep interval' ;;
    *) checkpoint_verdict='ERROR running checkpoint' ;;
  esac
  say "External checkpoint: $checkpoint_verdict"
  say "Hibermachy last reason code: $(hb_last_reason)"

  printf '\n'
  ask_result result "Cycle $label ($origin)"
  ask_evidence detail 'Sanitized corroborating observation:'

  # A cycle only counts when all four AC4 legs hold together.
  if [[ $result == PASS && $verify_status -eq 0 && $observed_down == yes ]]; then
    CONSECUTIVE=$((CONSECUTIVE + 1))
    row "Cycle $label ($origin)" PASS \
      "checkpoint=CONFIRMED; powered-down observed=yes; $detail"
    say "Consecutive successful cycles: $CONSECUTIVE of 3"
  else
    local recorded=$result operator_note=""
    if [[ $result == PASS ]]; then
      # Do not let an operator PASS stand as the recorded result when the
      # evidence contradicts it. Keep both facts in the record.
      recorded=FAIL
      operator_note="operator entered PASS, but a required AC4 leg is missing; "
      warn 'You marked PASS but a required leg of AC4 is missing. This cycle'
      warn 'is recorded FAIL and does not count toward the three cycles.'
    fi
    row "Cycle $label ($origin)" "$recorded" \
      "${operator_note}checkpoint=$checkpoint_verdict; powered-down observed=$observed_down; $detail"
    anomaly "Cycle $label ($origin) did not satisfy every AC4 leg"
  fi
  pause 'Press Enter to continue.'
}

# ══════════════════════════════════════════════════════════════════════════

mkdir -p "$RUN_DIR" "$STATE_DIR" "$BASELINE"

banner "Hibermachy attended hardware gate — candidate 625d5a2"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Bind the candidate, and state what this run does not claim"

say "Issue #26, requirement HBR-REQ-075. Candidate commit:"
note "$CANDIDATE_COMMIT"
printf '\n'
say 'Three criteria of issue #25 were resolved by owner determination rather'
say 'than by evidence. They are carried forward, not re-argued, and they'
say 'constrain what this release may ever claim:'
printf '\n'
note 'AC2  no clean environment exists; accepted unmet.'
note '     Never describe this release as clean-room qualified.'
note 'AC5  assistive technology is OUT OF SCOPE; accepted unmet.'
note '     Never describe this release as accessible or screen-reader tested.'
note 'AC7  independent review was met by owner determination, by an agent'
note '     and not a human. Never describe it as security certified.'
printf '\n'
say 'Recording these as accepted-unmet lets this run proceed without'
say 'inventing a pass for any of them.'
printf '\n'

if [[ ! -d $REPO/.git && ! -f $REPO/.git ]]; then
  warn "Not a git repository: $REPO"
  warn 'Set HIBERMACHY_REPO to the candidate checkout and re-run.'
  exit 1
fi

# The external checkpoint tool is tracked in the repository, on the ticket-26
# branch. Fail here with an explanation rather than part-way through a cycle.
if [[ ! -x $CHECKPOINT ]]; then
  warn "External checkpoint tool not found: $CHECKPOINT"
  warn 'AC4 cannot be satisfied without it. Check out the ticket-26 branch,'
  warn 'or point HIBERMACHY_REPO at a checkout that contains it, then re-run.'
  exit 1
fi

identity_ok=yes
actual_commit=$(git -C "$REPO" rev-parse --verify "${CANDIDATE_COMMIT}^{commit}" 2>/dev/null || echo missing)
actual_tree=$(git -C "$REPO" rev-parse "${CANDIDATE_COMMIT}^{tree}" 2>/dev/null || echo missing)
actual_archive=$(git -C "$REPO" archive --format=tar --prefix=hibermachy-helper-0.1.0/ \
                   "$CANDIDATE_COMMIT" 2>/dev/null | gzip -n -9 | sha256sum | awk '{print $1}' \
                 || echo missing)

[[ $actual_commit  == "$CANDIDATE_COMMIT" ]] || identity_ok=no
[[ $actual_tree    == "$CANDIDATE_TREE"   ]] || identity_ok=no
[[ $actual_archive == "$ARCHIVE_SHA256"   ]] || identity_ok=no

say "commit  $actual_commit"
say "tree    $actual_tree"
say "archive $actual_archive"
if [[ $identity_ok != yes ]]; then
  printf '\n'
  warn 'Candidate identity does NOT match the bound values.'
  warn 'AC7: changed bits are a different candidate. Stop, and cut a new one.'
  exit 1
fi
say 'Candidate identity matches the bound values.'

# Fixtures would silently turn this whole gate into a simulation.
printf '\n'
fixture_leak=no
for var in HBR_TEST_MODE HBR_LIFECYCLE_TEST_MODE HBR_TEST_CLOCK_START_MS \
           HBR_CONTRACT_PROBE HBR_POLICY_HELPER_PATH HBR_POLICY_HELPER_LAUNCHER \
           HBR_EFFECTIVE_POLICY_READER; do
  if [[ -n ${!var:-} ]]; then warn "$var is set in this environment"; fixture_leak=yes; fi
done
while IFS='=' read -r name _; do
  [[ $name == HIBERMACHY_SIM_* ]] || continue
  warn "$name is set in this environment"; fixture_leak=yes
done < <(env)
if [[ $fixture_leak == yes ]]; then
  printf '\n'
  warn 'Test fixtures or simulation variables are active.'
  warn 'This gate would measure fixtures, not hardware, and any pass'
  warn 'it produced would be worthless. Clear them and re-run.'
  exit 1
fi
say 'No test-mode or simulation variables are set; the real surface is live.'

mkdir -p "$RUN_DIR"
rec "# Hibermachy attended hardware gate — sanitized evidence record"
rec ""
rec "**Issue:** #26 (attended hardware gate and promotion), HBR-REQ-075"
rec "**Disposition:** in progress; no gate is passed until this record says so"
rec "**Candidate commit:** \`$CANDIDATE_COMMIT\`"
rec "**Candidate tree:** \`$CANDIDATE_TREE\`"
rec "**Source archive SHA-256:** \`$ARCHIVE_SHA256\`"
rec "**Signing fingerprint:** \`$SIGNING_KEY\`"
