rec "These were resolved by owner determination, not by evidence. They are"
rec "recorded as accepted-unmet and constrain every claim about this release."
rec ""
rec "| Criterion | Determination |"
rec "| --- | --- |"
rec "| AC2 clean environment | accepted unmet; no clean environment exists |"
rec "| AC5 accessibility | assistive technology out of scope; accepted unmet |"
rec "| AC7 independent review | met by owner determination; agent, not human |"
rec ""
rec "This release is not clean-room qualified, not accessibility certified,"
rec "not security certified, and claims no general version or hardware support."
rec ""
rec "## Candidate identity"
rec ""
rec "| Item | Result | Evidence |"
rec "| --- | --- | --- |"
row 'Candidate commit, tree and archive digest' PASS \
  "commit/tree/archive matched the bound values"
row 'Test fixtures and simulation variables absent' PASS \
  'no HBR_TEST_MODE, HBR_LIFECYCLE_TEST_MODE or HIBERMACHY_SIM_* set'

pause 'Press Enter to confirm the machine.'

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Confirm the designated machine and record the environment"

say 'The gate runs on ONE designated battery-equipped machine with'
say 'independently known-working suspend and hibernation, operator present.'
printf '\n'

os_name=$(. /etc/os-release 2>/dev/null && printf '%s' "${PRETTY_NAME:-unknown}")
kernel=$(uname -r)
has_battery=no; has_ac=no
for bat in /sys/class/power_supply/*; do
  [[ -r $bat/type ]] || continue
  case $(<"$bat/type") in
    Battery) has_battery=yes ;;
    Mains)   has_ac=yes ;;
  esac
done
pkgver() {
  local version
  version=$(pacman -Q "$1" 2>/dev/null | awk '{print $2}')
  printf '%s' "${version:-not installed}"
}

say "OS          $os_name"
say "Kernel      $kernel"
say "Omarchy     $(pkgver omarchy)"
say "Quickshell  $(pkgver quickshell)"
say "systemd     $(pkgver systemd)"
say "Battery     $has_battery        AC adapter  $has_ac"
printf '\n'

if [[ $has_battery != yes ]]; then
  warn 'No battery detected. The AC-deferral cycle of AC2 cannot be run here.'
  warn 'This is not the designated machine.'
  confirm 'Continue anyway, recording the AC-deferral cycle as NOT RUN?' || exit 1
fi

confirm 'Is this the designated machine, with you physically present?' || {
  say 'Stopping. Run this on the designated machine.'; exit 1; }

rec ""
rec "## Environment (sanitized)"
rec ""
rec "| Item | Value |"
rec "| --- | --- |"
rec "| OS | $os_name |"
rec "| Kernel | $kernel |"
rec "| Omarchy | $(pkgver omarchy) |"
rec "| Quickshell | $(pkgver quickshell) |"
rec "| systemd | $(pkgver systemd) |"
rec "| Battery present | $has_battery |"
rec "| AC adapter present | $has_ac |"
rec ""
rec "Recorded as a verified environment only for this exact version"
rec "combination. This is test evidence, not a promise of compatibility,"
rec "maintenance or support on any other combination."

pause 'Press Enter for the hibernation pre-flight.'

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Hibernation pre-flight — this stage never sleeps"

say 'AC1 requires that capability detection never itself triggers sleep.'
say 'Every check below is a read or a D-Bus query. None can initiate sleep.'
printf '\n'

rec ""
rec "## Hibernation pre-flight (non-sleeping)"
rec ""
rec "| Check | Result | Evidence |"
rec "| --- | --- | --- |"

states=$(cat /sys/power/state 2>/dev/null || echo '')
if [[ $states == *disk* ]]; then
  row 'Kernel supports hibernation' PASS "/sys/power/state = $states"
else
  row 'Kernel supports hibernation' FAIL "/sys/power/state = $states"
  warn 'This kernel cannot hibernate. The gate cannot pass here.'
fi

resume_dev=$(cat /sys/power/resume 2>/dev/null || echo '')
resume_off=$(cat /sys/power/resume_offset 2>/dev/null || echo '')
if [[ -n $resume_dev && $resume_dev != 0:0 ]]; then
  row 'Resume device configured' PASS "resume=$resume_dev offset=$resume_off"
else
  row 'Resume device configured' FAIL "resume=$resume_dev"
  warn 'No resume device. A hibernation image could be written but never'
  warn 'restored, which loses the session. Do not run the cycles.'
fi

# Hibernation writes its image to the swap area named by resume=, so zram
# sitting at a higher priority does not capture it. Priority still gets
# recorded, because zram plus hibernation is a common source of trouble.
swap_table=$(awk 'NR>1 {printf "%s(prio %s, %s kB free of %s) ", $1, $5, $3-$4, $3}' /proc/swaps)
image_limit=$(cat /sys/power/image_size 2>/dev/null || echo unknown)
resume_swap_free=$(awk '/^SwapFree:/ {print $2}' /proc/meminfo)
row 'Swap topology' 'NOT RUN' "$swap_table"
row 'Hibernation image size limit' 'NOT RUN' "${image_limit} bytes; SwapFree ${resume_swap_free} kB"

for m in CanHibernate CanSuspend CanSuspendThenHibernate; do
  # Output is: s "yes" — take field 2 and strip the quotes. Do not use
  # `tr -d s`, which would also eat the s in "yes".
  answer=$(busctl call org.freedesktop.login1 /org/freedesktop/login1 \
             org.freedesktop.login1.Manager "$m" 2>/dev/null \
             | awk '{gsub(/"/, "", $2); print $2}' || true)
  answer=${answer:-unavailable}
  if [[ $answer == yes ]]; then
    row "logind $m" PASS "$answer (read-only query; no sleep initiated)"
  else
    row "logind $m" FAIL "$answer"
  fi
done

# A distribution drop-in sets SYSTEMD_SLEEP_FREEZE_USER_SESSIONS=false on the
# sleep units. systemd warns this can misbehave specifically during
# suspend-then-hibernate, which is the exact unit staged sleep uses. It is
# vendor-owned configuration: record it, never change it.
# No match is the normal case and grep exits 1 for it; without `|| true`
# pipefail would abort the whole run here.
freeze_files=$(grep -rls 'SYSTEMD_SLEEP_FREEZE_USER_SESSIONS' \
                 /usr/lib/systemd /etc/systemd 2>/dev/null | tr '\n' ' ' || true)
if [[ -n $freeze_files ]]; then
  row 'User-session freeze overridden by vendor drop-in' 'NOT RUN' \
    "SYSTEMD_SLEEP_FREEZE_USER_SESSIONS set by: $freeze_files"
  printf '\n'
  warn 'A vendor drop-in disables user-session freezing on the sleep units.'
  warn 'systemd warns this can misbehave during suspend-then-hibernate,'
  warn 'which is the unit staged sleep uses. It is recorded as an'
  warn 'environment condition. Do NOT change it: that would mutate system'
  warn 'sleep policy and invalidate the run.'
  printf '\n'
else
  row 'User-session freeze overridden by vendor drop-in' 'NOT RUN' 'no override found'
fi

# suspend-then-hibernate is the staged-sleep unit. Whether it has ever run
# here decides how much weight past hibernations actually carry.
if journalctl -u systemd-suspend-then-hibernate.service -n 1 --no-pager 2>/dev/null \
     | grep -q 'No entries'; then
  row 'Staged-sleep unit previously exercised here' 'NOT RUN' \
    'systemd-suspend-then-hibernate.service has never run on this machine'
  warn 'The staged-sleep unit has never run here. Past direct hibernations'
  warn 'corroborate the hardware, but not this path. Treat a first-cycle'
  warn 'failure as a configuration question before a product question.'
else
  row 'Staged-sleep unit previously exercised here' 'NOT RUN' \
    'systemd-suspend-then-hibernate.service has prior journal entries'
fi

printf '\n'
say 'Pre-flight complete. No sleep was initiated by any check above.'
pause 'Press Enter to capture initial state.'

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Capture initial policy and configuration"

say 'AC1 requires initial policy and configuration to be recorded, and AC5'
say 'requires them verified restored afterwards. Capturing the baseline now.'
printf '\n'

rec ""
rec "## Initial state (AC1)"
rec ""
rec "| Check | Result | Evidence |"
rec "| --- | --- | --- |"

systemd-analyze cat-config systemd/sleep.conf  > "$BASELINE/sleep.conf.txt"  2>&1 || true
systemd-analyze cat-config systemd/logind.conf > "$BASELINE/logind.conf.txt" 2>&1 || true
hb_status_raw > "$BASELINE/hibermachy-status.json" 2>/dev/null || true
( cd "$REPO" && ./lifecycle/status status ) > "$BASELINE/lifecycle-status.json" 2>/dev/null || true
cat /proc/swaps > "$BASELINE/swaps.txt" 2>/dev/null || true

for f in sleep.conf logind.conf; do
  if [[ -s $BASELINE/$f.txt ]]; then
    row "Initial $f captured" PASS "$(wc -l < "$BASELINE/$f.txt") lines baselined"
  else
    row "Initial $f captured" 'NOT RUN' 'could not read effective configuration'
  fi
done
if is_json "$BASELINE/hibermachy-status.json"; then
  row 'Initial Hibermachy status snapshot captured' PASS 'IPC status baselined as valid JSON'
else
  row 'Initial Hibermachy status snapshot captured' 'NOT RUN' \
    'IPC target dev.hibermachy did not answer; is the plugin active?'
  warn 'The plugin did not answer on dev.hibermachy. The behavioural cases'
  warn 'below need it. Activate it before continuing, or record them NOT RUN.'
fi
if is_json "$BASELINE/lifecycle-status.json"; then
  row 'Initial lifecycle inventory captured' PASS 'lifecycle inventory baselined as valid JSON'
else
  row 'Initial lifecycle inventory captured' 'NOT RUN' 'lifecycle status unavailable or not JSON'
fi

say "Baseline written to: ${BASELINE/#$HOME/\~}"
pause 'Press Enter to arm the procedure.'

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Save your work, then explicitly arm"

warn 'Everything after this point can really suspend and hibernate.'
printf '\n'
say 'Before arming:'
step 'Save every open document and commit or stash any work in progress.'
step 'Close anything sensitive you would not want left on screen at resume.'
step 'Make sure you can physically reach the power button and the charger.'
printf '\n'
say 'AC1 requires an explicit arm after this warning. Capability detection'
say 'has already run and never slept the machine; arming is a separate act.'
printf '\n'

readonly ARM_PHRASE='ARMED BY OPERATOR: work saved; designated machine confirmed; real sleep authorized'
say 'Type this line exactly to arm:'
printf '\n  %s%s%s\n\n' "$BOLD" "$ARM_PHRASE" "$RESET"
printf '  > '
read -r arm_input || true
if [[ $arm_input != "$ARM_PHRASE" ]]; then
  printf '\n'
  warn 'That did not match. The procedure is NOT armed and will stop here.'
  rec ""
  rec "## Arm"
  rec ""
  rec "| Item | Result | Evidence |"
  rec "| --- | --- | --- |"
  row 'Explicit operator arm' 'NOT RUN' 'arm phrase not entered; run stopped before any sleep'
  rec ""
  rec "**Final decision:** BLOCKED — the procedure was never armed."
  printf '\n'
  say "Partial record: ${RECORD/#$HOME/\~}"
  exit 1
fi
ARMED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
rec ""
rec "## Arm"
rec ""
rec "| Item | Result | Evidence |"
rec "| --- | --- | --- |"
row 'Save-work warning acknowledged' PASS 'operator warned before arming'
row 'Non-sleeping capability detection confirmed' PASS \
  'pre-flight completed in stage 3 without initiating sleep'
row 'Explicit operator arm' PASS "exact arm phrase entered at $ARMED_AT UTC"
printf '\n'
say "Armed at $ARMED_AT UTC."
pause 'Press Enter to begin the separate behavioural cases.'

rec ""
rec "## Separate attended cases (AC3)"
rec ""
rec "These do not count toward the three consecutive cycles."
rec ""
rec "| Case | Result | Evidence |"
rec "| --- | --- | --- |"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Case 1 of 7 — Stay Awake suppresses automatic staged sleep"

say 'Automatic staged sleep must be suppressed while Stay Awake is on.'
say 'No sleep may occur in this case.'
printf '\n'
step 'Turn Stay Awake ON from the Omarchy menu (Super+Space).'
pause 'Press Enter once Stay Awake is on.'
printf '\n'
suppression_case 'Stay Awake suppression' 'HBR-STAY-AWAKE-ENABLED' automaticBlockerReasonCode
printf '\n'
step 'Turn Stay Awake back OFF before continuing.'
pause 'Press Enter once Stay Awake is off.'

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Case 2 of 7 — a compositor idle inhibitor suppresses automatic sleep"

say 'A Wayland idle inhibitor must suppress automatic staged sleep, while a'
say 'separately confirmed manual request may still bypass it.'
printf '\n'
step 'Start something that holds a compositor idle inhibitor.'
note 'Playing a video full-screen in a browser is the usual way.'
pause 'Press Enter once the inhibitor is active.'
printf '\n'
suppression_case 'Compositor idle inhibition' 'HBR-COMPOSITOR-IDLE-INHIBITED' automaticBlockerReasonCode
printf '\n'
step 'Stop the inhibitor before continuing.'
pause 'Press Enter once it is released.'

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Case 3 of 7 — a system sleep inhibitor refuses a manual request"

say 'Manual staged sleep bypasses Stay Awake and compositor inhibition, but'
say 'it must still honour a system (logind) sleep inhibitor and be REFUSED.'
printf '\n'
say 'In another terminal, hold a system sleep inhibitor:'
printf '\n  %ssystemd-inhibit --what=sleep --why="hibermachy gate" sleep 600%s\n\n' "$BOLD" "$RESET"
pause 'Press Enter once the inhibitor is held.'
printf '\n'
say 'Now request manual staged sleep. It must be refused, not honoured:'
printf '\n  %somarchy-shell dev.hibermachy requestStagedSleep%s\n\n' "$BOLD" "$RESET"
note 'Expected receipt: kind="refused", reasonCode="HBR-SLEEP-SYSTEM-INHIBITED"'
note 'The machine must NOT sleep.'
pause 'Run it, then press Enter.'
printf '\n'
show_status
manual_block=$(hb_field manualBlockerReasonCode)
say "manualBlockerReasonCode = $manual_block"
ask_result r_inhibit 'System-inhibitor refusal'
ask_evidence d_inhibit 'Receipt kind and reason code you saw (and that no sleep occurred):'
row 'System-inhibitor refusal' "$r_inhibit" \
  "expected refused/HBR-SLEEP-SYSTEM-INHIBITED; manualBlockerReasonCode=$manual_block; $d_inhibit"
[[ $r_inhibit == FAIL ]] && anomaly 'System-inhibitor refusal failed'
printf '\n'
step 'Release the system inhibitor (Ctrl-C the systemd-inhibit command).'
pause 'Press Enter once released.'

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "Case 4 of 7 — fresh activity is required to re-arm"

say 'After activation, reload, a relevant policy change, or a prior staged'
say 'sleep, automatic staged sleep must wait for NEW activity before it can'
say 'run again. It must not fire off a stale idle observation.'
printf '\n'
rearm=$(hb_field rearmRequired)
fresh=$(hb_field freshActivityObserved)
say "rearmRequired        = $rearm"
say "freshActivityObserved = $fresh"
say "automaticBlockerReasonCode = $(hb_field automaticBlockerReasonCode)"
note 'Expected while waiting to re-arm: HBR-FRESH-ACTIVITY-REQUIRED'
printf '\n'
step 'Move the mouse or press a key to produce fresh activity, then re-check.'
pause 'Press Enter after producing activity.'
say "rearmRequired is now        = $(hb_field rearmRequired)"
say "freshActivityObserved is now = $(hb_field freshActivityObserved)"
printf '\n'
ask_result r_rearm 'Fresh-activity re-arm'
ask_evidence d_rearm 'What the re-arm fields did before and after activity:'
row 'Fresh-activity re-arm' "$r_rearm" "$d_rearm"
[[ $r_rearm == FAIL ]] && anomaly 'Fresh-activity re-arm failed'

# ── Stage 10 ──────────────────────────────────────────────────────────────
stage "Case 5 of 7 — reload while latched"

say 'Reloading the plugin while it is latched must not replay a request,'
say 'must not restore a countdown, and must not keep a stale capability or'
say 'inhibitor snapshot. It fails closed and demands fresh activity again.'
printf '\n'
warn 'This case has NO merge-gate coverage for the same-boot path.'
note 'The same-boot reload reason code HBR-SLEEP-SERVICE-RECREATED is'
note 'present in the source but no automated test exercises it. This'
note 'attended run is its first and only exercise, so look carefully.'
printf '\n'
step 'Reload or disable-and-re-enable the Hibermachy plugin.'
pause 'Press Enter once the plugin has come back.'
printf '\n'
show_status
say "Last outcome reason code: $(hb_last_reason)"
note 'Expect rearmRequired=true after reload, and no replayed request.'
printf '\n'
ask_result r_reload 'Reload while latched'
ask_evidence d_reload 'Reason code and re-arm state after reload:'
row 'Reload while latched' "$r_reload" "no merge-gate coverage for same-boot path; $d_reload"
[[ $r_reload == FAIL ]] && anomaly 'Reload while latched failed'

# ── Stage 11 ──────────────────────────────────────────────────────────────
stage "Case 6 of 7 — deliberate fallback to ordinary suspend"

say 'When hibernation is unavailable but suspend is executable, a manual'
say 'request must fall back to ordinary suspend, say so in the confirmation,'
say 'and must NOT claim hibernation in its result.'
printf '\n'
say "fallbackAvailable = $(hb_field fallbackAvailable)"
say "heroStatus        = $(hb_field heroStatus)"
printf '\n'
note 'Expected on fallback: selectedMode="suspend", outcome "Degraded",'
note 'reasonCode "HBR-SLEEP-SUSPEND-FALLBACK". The confirmation text must'
note 'name ordinary suspend.'
printf '\n'
warn 'Reaching this state on real hardware needs hibernation to be genuinely'
warn 'unexecutable. Do NOT mutate system sleep policy or swap to force it.'
warn 'If you cannot reach it without mutating policy, record NOT RUN.'
printf '\n'
ask_result r_fallback 'Deliberate suspend fallback'
ask_evidence d_fallback 'Confirmation wording and result, or why NOT RUN:'
row 'Deliberate suspend fallback' "$r_fallback" "$d_fallback"
[[ $r_fallback == FAIL ]] && anomaly 'Deliberate suspend fallback failed'

# ── Stage 12 ──────────────────────────────────────────────────────────────
stage "Case 7 of 7 — early wake during the suspended interval"

say 'Waking during the suspended interval, before the hibernate delay'
say 'elapses, must not produce an invented hibernation claim. The latch'
say 'stays set until fresh activity.'
printf '\n'
warn 'This case has NO merge-gate coverage.'
note 'HBR-SLEEP-EARLY-WAKE is enumerated in the source but no automated'
note 'test exercises it. This attended run is its first and only exercise.'
printf '\n'
say 'This case does involve a real suspend, but a deliberately short one.'
step 'Request staged sleep, let the machine suspend, then wake it EARLY,'
step 'well before the hibernate delay would transition it to hibernation.'
pause 'Press Enter when you are back from the early wake.'
printf '\n'
show_status
say "Last outcome reason code: $(hb_last_reason)"
note 'The result must not claim hibernation was confirmed.'
printf '\n'
ask_result r_early 'Early wake'
ask_evidence d_early 'Reason code, and confirmation that no hibernation was claimed:'
row 'Early wake' "$r_early" "no merge-gate coverage; $d_early"
[[ $r_early == FAIL ]] && anomaly 'Early wake failed'

pause 'Press Enter to begin the three consecutive physical cycles.'

rec ""
rec "## Consecutive staged-sleep / hibernation / resume cycles (AC2, AC4)"
rec ""
rec "Each cycle requires all of: an external pre-sleep checkpoint, the typed"
rec "request origin, an external observation of the powered-down state,"
rec "same-session restoration, and sanitized corroboration. A Hibermachy"
rec "Completed result cannot certify hibernation on its own."
rec ""
rec "| Cycle | Result | Evidence |"
rec "| --- | --- | --- |"

# ── Stage 13 ──────────────────────────────────────────────────────────────
stage "Cycle 1 of 3 — automatic request"

if physical_cycle cycle-1 'automatic request after idle expiry'; then
  step 'Make sure Stay Awake is OFF and no idle inhibitor is held.'
  step 'Produce fresh activity, then STOP TOUCHING the machine.'
  step 'Let the idle delay expire so staged sleep starts on its own.'
  step 'Let it suspend, then let the hibernate delay transition it to hibernate.'
  step 'Watch for the machine to power down fully, then power it back on.'
  printf '\n'
  warn 'Do not press any key in this terminal until the machine has resumed.'
  pause 'Press Enter only after the machine has resumed.'
  finish_cycle cycle-1 'automatic request after idle expiry'
else
  warn 'Skipping this cycle: the pre-sleep checkpoint could not be recorded.'
  pause 'Press Enter to continue.'
fi

# ── Stage 14 ──────────────────────────────────────────────────────────────
stage "Cycle 2 of 3 — confirmed manual request"

if physical_cycle cycle-2 'confirmed manual request'; then
  step 'Open the Omarchy menu with Super+Space.'
  step 'Choose "Suspend then Hibernate".'
  step 'Read the confirmation dialog, then confirm it.'
  note 'The confirmation must name the selected mode, the Stay Awake and'
  note 'compositor-inhibitor bypass, and continued system-inhibitor enforcement.'
  step 'Let it suspend, then hibernate. Watch it power down, then power it on.'
  printf '\n'
  pause 'Press Enter only after the machine has resumed.'
  finish_cycle cycle-2 'confirmed manual request'
else
  warn 'Skipping this cycle: the pre-sleep checkpoint could not be recorded.'
  pause 'Press Enter to continue.'
fi

# ── Stage 15 ──────────────────────────────────────────────────────────────
stage "Cycle 3 of 3 — AC deferral, then disconnect"

if [[ $has_battery != yes ]]; then
  warn 'No battery on this machine, so AC deferral cannot be exercised.'
  row 'Cycle cycle-3 (AC deferral then disconnect)' 'NOT RUN' 'no battery present'
else
  if physical_cycle cycle-3 'AC deferral then disconnect'; then
  step 'Connect AC power before starting.'
  step 'Begin staged sleep and let the machine suspend.'
  step 'With AC still connected, confirm it STAYS suspended and does not'
  step '  transition to hibernation while on AC.'
  step 'Now disconnect AC while it is still suspended.'
  step 'Confirm it then transitions to hibernation and powers down.'
  step 'Power it back on.'
  printf '\n'
  note 'AC deferral depends on the requested AC-power behaviour. If system'
  note 'policy was never applied, deferral may simply not be in effect;'
  note 'record what actually happened rather than what was expected.'
  printf '\n'
  pause 'Press Enter only after the machine has resumed.'
  finish_cycle cycle-3 'AC deferral then disconnect'
  else
    warn 'Skipping this cycle: the pre-sleep checkpoint could not be recorded.'
    pause 'Press Enter to continue.'
  fi
fi

rec ""
rec "**Consecutive successful cycles:** $CONSECUTIVE of 3"
rec ""
rec "**Anomalies recorded:** $ANOMALIES"

# ── Stage 16 ──────────────────────────────────────────────────────────────
stage "Restore and verify the initial state"

say 'AC5 requires initial policy and configuration to be verified restored.'
printf '\n'

rec ""
rec "## Restoration (AC5)"
rec ""
rec "| Check | Result | Evidence |"
rec "| --- | --- | --- |"

systemd-analyze cat-config systemd/sleep.conf  > "$RUN_DIR/final-sleep.conf.txt"  2>&1 || true
systemd-analyze cat-config systemd/logind.conf > "$RUN_DIR/final-logind.conf.txt" 2>&1 || true

for f in sleep.conf logind.conf; do
  if [[ ! -s $BASELINE/$f.txt ]]; then
    row "$f restored to initial state" 'NOT RUN' 'no baseline captured'
  elif diff -q "$BASELINE/$f.txt" "$RUN_DIR/final-$f.txt" >/dev/null 2>&1; then
    row "$f restored to initial state" PASS 'byte-identical to the baseline'
  else
    row "$f restored to initial state" FAIL 'differs from the baseline'
    warn "$f differs from the captured baseline. Investigate before promoting."
    diff "$BASELINE/$f.txt" "$RUN_DIR/final-$f.txt" 2>&1 | head -20 | sed 's/^/  /'
    anomaly "$f was not restored to its initial state"
  fi
done

( cd "$REPO" && ./lifecycle/status status ) > "$RUN_DIR/final-lifecycle-status.json" 2>/dev/null || true
if is_json "$BASELINE/lifecycle-status.json" && is_json "$RUN_DIR/final-lifecycle-status.json"; then
  if diff -q "$BASELINE/lifecycle-status.json" "$RUN_DIR/final-lifecycle-status.json" >/dev/null 2>&1; then
    row 'Lifecycle inventory unchanged' PASS 'identical to the baseline'
  else
    row 'Lifecycle inventory unchanged' 'NOT RUN' \
      'differs from baseline; review the diff before promoting'
    warn 'The lifecycle inventory changed during the run. Review it.'
  fi
else
  row 'Lifecycle inventory unchanged' 'NOT RUN' 'baseline or final inventory unavailable'
fi

ask_result r_unrelated 'Unrelated configuration and state untouched'
ask_evidence d_unrelated 'What you checked outside Hibermachy ownership:'
row 'Unrelated configuration and state untouched' "$r_unrelated" "$d_unrelated"

# ── Stage 17 ──────────────────────────────────────────────────────────────
stage "Gate decision and promotion handoff"

# Re-verify identity: promotion is only ever of the unchanged candidate.
final_archive=$(git -C "$REPO" archive --format=tar --prefix=hibermachy-helper-0.1.0/ \
                  "$CANDIDATE_COMMIT" 2>/dev/null | gzip -n -9 | sha256sum | awk '{print $1}' \
                || echo missing)
identity_still_ok=no
[[ $final_archive == "$ARCHIVE_SHA256" ]] && identity_still_ok=yes

# grep -c already prints 0 when nothing matches, and then exits 1, so a
# `|| echo 0` fallback would append a second zero and corrupt the count.
fails=$(grep -c '^| .* | FAIL |' "$RECORD" 2>/dev/null || true)
notruns=$(grep -c '^| .* | NOT RUN |' "$RECORD" 2>/dev/null || true)
fails=${fails:-0}
notruns=${notruns:-0}

rec ""
rec "## Gate decision"
rec ""
rec "| Item | Value |"
rec "| --- | --- |"
rec "| Consecutive successful cycles | $CONSECUTIVE of 3 |"
rec "| Anomalies | $ANOMALIES |"
rec "| Rows marked FAIL | $fails |"
rec "| Rows marked NOT RUN | $notruns |"
rec "| Candidate unchanged at close | $identity_still_ok |"
rec ""

GATE_PASSED=no
if [[ $CONSECUTIVE -ge 3 && $ANOMALIES -eq 0 && $fails -eq 0 && $identity_still_ok == yes ]]; then
  GATE_PASSED=yes
fi

say "Consecutive successful cycles : $CONSECUTIVE of 3"
say "Anomalies                     : $ANOMALIES"
say "Rows marked FAIL              : $fails"
say "Rows marked NOT RUN           : $notruns"
say "Candidate unchanged at close  : $identity_still_ok"
printf '\n'

if [[ $GATE_PASSED == yes ]]; then
  printf '  %s%sHardware gate: PASSED%s\n\n' "$BOLD" "$GREEN" "$RESET"
  rec "**Hardware gate:** PASSED"
  rec ""
  rec "Passed on this exact environment only. This records test evidence and"
  rec "claims no general version support, hardware compatibility, security"
  rec "certification or accessibility certification."
else
  printf '  %s%sHardware gate: BLOCKED%s\n\n' "$BOLD" "$RED" "$RESET"
  rec "**Hardware gate:** BLOCKED"
  rec ""
  rec "Promotion is blocked. Every criterion must hold with no anomaly, no"
  rec "FAIL row, three consecutive cycles, and an unchanged candidate."
  say 'Promotion is blocked. Nothing has been published.'
fi
printf '\n'

rec ""
rec "## Promotion"
rec ""
rec "| Check | Result | Evidence |"
rec "| --- | --- | --- |"
row 'Sanitized verification record published' 'NOT RUN' 'publish step is performed by the release operator'
row 'Unchanged candidate promoted' 'NOT RUN' 'not performed by this procedure'
row 'Public metadata/artifact/checksum/download smoke checks' 'NOT RUN' 'follows promotion'
row 'Lifecycle discovery smoke check' 'NOT RUN' 'follows promotion'
rec ""
rec "**Final decision:** $( [[ $GATE_PASSED == yes ]] \
  && echo 'hardware gate passed; promotion not yet performed' \
  || echo 'BLOCKED — hardware gate did not pass' )"
rec ""
rec "Published artifacts are immutable per version (AC7). A failure creates a"
rec "new candidate identity, and a post-release defect is corrected only in a"
rec "new release, never by replacing a published artifact in place."

_clear
printf '\n%s%s  Attended hardware gate finished%s\n\n' "$BOLD" "$BLUE" "$RESET"
say "Evidence record: ${RECORD/#$HOME/\~}"
say "Checkpoints:     ${STATE_DIR/#$HOME/\~}"
printf '\n'
warn 'This procedure has published NOTHING. It has not pushed, signed,'
warn 'tagged, created a release, or promoted anything.'
printf '\n'

if [[ $GATE_PASSED == yes ]]; then
  say 'The gate passed. Promotion is a separate, deliberate act that you'
  say 'perform by hand, with the finished evidence record in front of you.'
  printf '\n'
  say 'Before you publish anything, re-read the record and confirm:'
  step 'Every row you expected to pass says PASS, and no row says FAIL.'
  step 'Every NOT RUN row is one you consciously accepted.'
  step 'Nothing in the record claims clean-room, accessibility, screen-reader'
  step '  or security qualification.'
  step 'The candidate is still unchanged.'
  printf '\n'
  say 'Promotion, when you choose to do it, is roughly:'
  printf '\n'
  note "  git push origin $CANDIDATE_COMMIT:refs/heads/release-0.1.0"
  note "  gh release create v0.1.0 \\"
  note "    handoff/candidate-625d5a2/hibermachy-helper-0.1.0.tar.gz \\"
  note "    handoff/candidate-625d5a2/hibermachy-helper-0.1.0.tar.gz.sig \\"
  note "    --target release-0.1.0 --prerelease"
  printf '\n'
  warn 'Those commands are one-way. Once 0.1.0 is public with those bytes,'
  warn 'AC7 forbids replacing them: a defect needs a new version entirely.'
  warn 'Check them yourself before running them; do not paste them blind.'
else
  say 'Do not promote. Investigate the blocked rows, fix the cause, and note'
  say 'that changing any shipped bit produces a NEW candidate identity, which'
  say 'requires this whole gate to run again from the beginning.'
fi
printf '\n'
